uniform float speed : 0.0 .. 5.0 = 0.4;
uniform float width : 0.02 .. 0.5 = 0.15;
uniform float sat   : 0.0 .. 1.0 = 0.9;
uniform float sat2  : 0.0 .. 1.0 = 0.5;
uniform float hue   : 0.0 .. 1.0 = 0.55;
uniform float hue2  : 0.0 .. 1.0 = 0.75;
uniform float satmix: 0.0 .. 1.0 = 0.5;

state fixed ph1;
state fixed ph2;

void update() {
  ph1 = fract(ph1 + fixed(dt * speed * 0.06));
  ph2 = fract(ph2 + fixed(dt * speed * 0.04));
}

vec3 shade(Led led) {
  fixed s = fixed(led.s);
  fixed u = fixed(led.uv.y);

  // two slow-drifting vertical curtains, each a narrow band along the helix
  fixed a1 = fract(s - ph1);
  fixed a2 = fract(s - ph2);

  fixed b1 = abs(a1 - fixed(0.5));
  fixed b2 = abs(a2 - fixed(0.5));
  fixed w1 = clamp((fixed(width) - b1) * fixed(8.0), fixed(0.0), fixed(1.0));
  fixed w2 = clamp((fixed(width) - b2) * fixed(8.0), fixed(0.0), fixed(1.0));

  // vertical shimmer: slow wave down the height of the cylinder
  fixed sh = sin(u * fixed(3.0) + ph1) * fixed(0.5) + fixed(0.5);
  w1 = w1 * sh;

  // colour each curtain with its own hue/sat, then blend
  vec3 c1 = hsv2rgb(hue * fixed(1.0), fixed(satmix), fixed(1.0));
  vec3 c2 = hsv2rgb(hue2 * fixed(1.0), fixed(satmix), fixed(1.0));
  vec3 c  = mix(c1, c2, w2);

  // overall brightness follows curtain coverage, with a dim ambient floor
  fixed bright = max(w1, w2);
  return c * float(bright * fixed(0.8) + fixed(0.1));
}
